<script setup lang="ts">
import {ref,watch,nextTick,computed} from 'vue';import NetworkView from './NetworkView.vue';import FaultPicker from './FaultPicker.vue';import {apiError} from './apiError';
const network=defineModel<any>({required:true});const failures=defineModel<number[]>('failures',{required:true});const props=defineProps<{disabled:boolean;placement:{wind_node:number;pv_node:number};focus?:string}>();
const draft=ref<any>(null);const message=ref('');const valid=ref(false);const initial=ref('');
const editorTab=ref('拓扑与故障');
const showNodes=computed(()=>editorTab.value==='节点编辑');
const showLines=computed(()=>editorTab.value==='线路编辑');
watch(network,v=>{draft.value=v?JSON.parse(JSON.stringify(v)):null;initial.value=JSON.stringify(draft.value);valid.value=!!v},{immediate:true,deep:true});
watch(draft,()=>{valid.value=JSON.stringify(draft.value)===initial.value&&!!network.value},{deep:true});
async function example(){try{const r=await fetch('/api/network/case33');if(!r.ok)throw Error('示例读取失败');draft.value={name:'IEEE33示例电网',base_voltage_kv:12.66,...await r.json()};message.value='已载入示例草稿，校验并应用后生效。'}catch(e){message.value=String(e)}}
function empty(){draft.value={name:'阿拉山口电网（待录入）',source:'依据SourceData图纸人工录入；待核实线路参数',base_voltage_kv:10,nodes:[{node:1,name:'上级电源',type:3,pd_kw:0,qd_kvar:0,vm_init_pu:1},{node:2,name:'负荷节点',type:1,pd_kw:1,qd_kvar:0,vm_init_pu:1}],lines:[{line:1,name:'待核实线路',from_node:1,to_node:2,r_ohm:0,x_ohm:0,status:1}]};message.value='新建的是录入模板，请按图纸填写端点、负荷和阻抗后应用。'}
function addNode(){const id=Math.max(...draft.value.nodes.map((n:any)=>n.node))+1;draft.value.nodes.push({node:id,name:'节点'+id,type:1,pd_kw:0,qd_kvar:0,vm_init_pu:1})}
function addLine(){draft.value.lines.push({line:Math.max(0,...draft.value.lines.map((l:any)=>l.line))+1,name:'新线路',from_node:1,to_node:draft.value.nodes.at(-1).node,r_ohm:0,x_ohm:0,status:1})}
async function apply(){try{const r=await fetch('/api/network/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(draft.value)});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));network.value=d;props.placement.wind_node=d.nodes.some((n:any)=>n.node===props.placement.wind_node)?props.placement.wind_node:1;props.placement.pv_node=d.nodes.some((n:any)=>n.node===props.placement.pv_node)?props.placement.pv_node:1;failures.value=failures.value.filter(id=>d.lines.some((l:any)=>l.line===id&&l.status));await nextTick();message.value='网络校验通过并已应用，请保存工程。';valid.value=true}catch(e){message.value=String(e)}}
function exportJson(){const u=URL.createObjectURL(new Blob([JSON.stringify(draft.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='network.json';a.click();URL.revokeObjectURL(u)}
async function upload(e:Event){const input=e.target as HTMLInputElement;try{const f=input.files?.[0];if(f){if(f.size>500000)throw Error('文件过大');const d=JSON.parse(await f.text());if(!Array.isArray(d.nodes)||!Array.isArray(d.lines))throw Error('需要nodes和lines数组');draft.value=d;message.value='JSON已载入草稿，请校验并应用。'}}catch(e){message.value=String(e)}finally{input.value=''}}
</script>
<template><article><div class="editor-tabs" role="tablist" aria-label="电网拓扑编辑"><button v-for="name in ['拓扑与故障','节点编辑','线路编辑']" :key="name" role="tab" :aria-selected="editorTab===name" :class="{current:editorTab===name}" @click="editorTab=name">{{name}}</button></div><h3>{{focus==='电网节点'?'电网节点编辑':focus==='电网线路'?'电网线路编辑':'电网拓扑与故障点编辑'}}</h3><p v-if="focus==='电网节点'">当前页面显示节点编辑表，可添加或删除节点并修改节点编号、名称、有功负荷和无功负荷。修改后点击“校验并应用网络”。</p><p v-else-if="focus==='电网线路'">当前页面显示线路编辑表，可添加或删除线路并修改端点、阻抗、容量和投运状态。修改后点击“校验并应用网络”。</p><p v-else>修改草稿后点击“校验并应用”，再保存工程。支持最多100节点的连通辐射网；故障断线请在已应用网络上设置。阻抗单位Ω，负荷单位kW/kvar。逐设备调度使用每线路kVA容量；旧IEEE33入口仍使用统一支路限额。</p><div class="actions"><button @click="example" :disabled="disabled">载入IEEE33示例草稿</button><button @click="empty" :disabled="disabled">新建阿拉山口网络草稿</button><label class="button">导入网络JSON<input type="file" accept=".json" hidden @change="upload" :disabled="disabled"></label></div><p class="notice" v-if="message">{{message}}</p><template v-if="draft"><label>网络名称<input v-model="draft.name" :disabled="disabled"></label><label>基准电压 / kV<input type="number" v-model.number="draft.base_voltage_kv" :disabled="disabled"></label><label>数据来源<input v-model="draft.source" :disabled="disabled"></label><details v-if="showNodes" open><summary>节点编辑</summary><div class="scroll"><table><tr><th>编号</th><th>名称</th><th>有功负荷</th><th>无功负荷</th><th></th></tr><tr v-for="(n,i) in draft.nodes" :key="i"><td><input type="number" v-model.number="n.node" :disabled="disabled"></td><td><input v-model="n.name" :disabled="disabled"></td><td><input type="number" v-model.number="n.pd_kw" :disabled="disabled"></td><td><input type="number" v-model.number="n.qd_kvar" :disabled="disabled"></td><td><button @click="draft.nodes.splice(i,1)" :disabled="disabled||n.node===1">删除</button></td></tr></table></div><button @click="addNode" :disabled="disabled">添加节点</button></details><details v-if="showLines" open><summary>线路编辑</summary><div class="scroll"><table><tr><th>编号</th><th>线路名称</th><th>首节点</th><th>末节点</th><th>电阻 / Ω</th><th>电抗 / Ω</th><th>容量 / kVA（可空）</th><th>投运</th><th></th></tr><tr v-for="(l,i) in draft.lines" :key="i"><td><input type="number" v-model.number="l.line" :disabled="disabled"></td><td><input v-model="l.name" :disabled="disabled"></td><td><input type="number" v-model.number="l.from_node" :disabled="disabled"></td><td><input type="number" v-model.number="l.to_node" :disabled="disabled"></td><td><input type="number" step="any" v-model.number="l.r_ohm" :disabled="disabled"></td><td><input type="number" step="any" v-model.number="l.x_ohm" :disabled="disabled"></td><td><input type="number" min="0" :value="l.capacity_kva" @input="l.capacity_kva=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value)" :disabled="disabled"></td><td><select v-model.number="l.status" :disabled="disabled"><option :value="1">投运</option><option :value="0">备用</option></select></td><td><button @click="draft.lines.splice(i,1)" :disabled="disabled">删除</button></td></tr></table></div><button @click="addLine" :disabled="disabled">添加线路</button></details><div class="actions"><button @click="apply" :disabled="disabled">校验并应用网络</button><button @click="exportJson">导出草稿JSON</button><span>{{valid?'已应用':'草稿修改尚未应用'}}</span></div></template><template v-if="network&&editorTab==='拓扑与故障'"><h3>已应用网络 · 故障点设置</h3><p>点击图中线路或勾选故障点。红色虚线表示故障；启用运行阶段时，请在各阶段单独设置故障与恢复。</p><NetworkView :network="network" :placement="placement" :failed-lines="failures" :editable="!disabled" @toggle-line="id=>failures=failures.includes(id)?failures.filter(n=>n!==id):[...failures,id]"/><FaultPicker v-model="failures" :lines="network.lines" :disabled="disabled"/></template></article></template>
<style scoped>.editor-tabs{display:flex;gap:8px;margin-bottom:20px}.editor-tabs .current{background:#087b7b;color:white}details{margin:18px 0}summary{cursor:pointer}input{width:100px;padding:7px;border:1px solid #cbdde0}label{display:flex;gap:12px;margin:12px 0;align-items:center}label input{width:360px}td:nth-child(2) input{width:180px}.scroll{max-height:420px;overflow:auto;margin:12px 0}</style>

